const { Component, xml, mount, signal } = owl;

class CartonCounter extends Component {
  static template = xml`
    <div>
      <span id="n" t-out="this.cartons()"/>
      <button id="plus" t-on-click="() => this.change(1)">+</button>
      <button id="minus" t-on-click="() => this.change(-1)">-</button>
      <form t-on-submit.prevent="this.reset"><button id="reset">Reset</button></form>
    </div>`;
  cartons = signal(0);
  change(delta) {
    this.cartons.set(Math.max(0, this.cartons() + delta));
  }
  reset() {
    this.cartons.set(0);
  }
}
await mount(CartonCounter, document.body);
